mapper.update:
update t_int_meeting_state
set mst_updated_at = sysdate()
, mst_mic_enabled = #{micEnabled,jdbcType=TINYINT}
, mst_cam_enabled = #{camEnabled,jdbcType=TINYINT}
, mst_speaker_volume = #{speakerVolume,jdbcType=TINYINT}
, mst_device_json = #{deviceJson,jdbcType=VARCHAR}
where mst_session_id = #{sessionId}

update t_int_meeting_state
set mst_heartbeat_at = sysdate(), mst_updated_at = sysdate()
where mst_session_id = #{sessionId}

update t_int_meeting_state
set mst_current_question = mst_current_question + 1, mst_updated_at = sysdate()
where mst_session_id = #{sessionId}

mapper.select:
select cpt_id as id, cpt_session_id as sessionId, cpt_status as status
from t_int_copilot
where cpt_id = #{id}

select s.ses_id as sessionId, ifnull(u.nick_name, u.user_name) as candidateName, p.pos_title as positionTitle, date_format(s.ses_end_at, '%Y-%m-%d') as interviewDate, ifnull(s.ses_rec_duration_sec, 0) as durationSec, s.ses_status as status, s.ses_mode as mode, s.ses_rec_url as recUrl, s.ses_rec_access_level as recAccessLevel, date_format(s.ses_rec_expires_at, '%Y-%m-%d') as recExpiresAt from t_int_session s join t_pos p on p.pos_id = s.ses_position_id join t_tal t on t.tal_id = s.ses_candidate_id join sys_user u on u.user_id = t.tal_user_id where p.pos_company_id = #{companyId} and s.ses_rec_url is not null
and s.ses_id = #{sessionId}
and (u.nick_name like concat('%', #{candidate}, '%') or u.user_name like concat('%', #{candidate}, '%'))
and s.ses_end_at >= #{from}
and s.ses_end_at <= concat(#{to}, ' 23:59:59')
order by s.ses_end_at desc, s.ses_id desc
